import{_ as i,a0 as r,w as C,s as d,I as a,x as s,a1 as p,A as l,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const O=JSON.parse('{"title":"通過寫“猜數字”遊戲學習 Fortran | LCTT x X-CMD","titleTemplate":false,"description":"通過寫“猜數字”遊戲學習 Fortran | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過寫“猜數字”遊戲學習 Fortran | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過寫“猜數字”遊戲學習 Fortran | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20210104 Learn Fortran by writing a -guess the number- game","title":"通過寫“猜數字”遊戲學習 Fortran","tag":"202110","desc":""},"relativePath":"202110/20210104 Learn Fortran by writing a -guess the number- game.md","filePath":"[post].md"}'),u={name:"202110/20210104 Learn Fortran by writing a -guess the number- game.md"};function T(E,n,g,N,f,m){const e=r("Link"),t=r("rb");return C(),d("div",null,[n[32]||(n[32]=a("h1",{id:"通過寫-猜數字-遊戲學習-fortran",tabindex:"-1"},[s("通過寫“猜數字”遊戲學習 Fortran "),a("a",{class:"header-anchor",href:"#通過寫-猜數字-遊戲學習-fortran","aria-label":"Permalink to “通過寫“猜數字”遊戲學習 Fortran”"},"​")],-1)),n[33]||(n[33]=a("blockquote",null,[a("p",null,"Fortran 是在打孔卡時代編寫的語言，因此它的語法非常有限。但你仍然可以用它編寫有用和有趣的程序。")],-1)),n[34]||(n[34]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202110/04/125311k6uwzpybabayyoag.jpg",alt:""})],-1)),a("p",null,[n[1]||(n[1]=s("Fortran 77 是我學習的第一門編譯型編程語言。一開始時，我自學瞭如何在 Apple II 上用 BASIC 編寫程序，後來又學會在 DOS 上用 QBasic 編寫程序。但是當我去大學攻讀物理學時，我又學習了 ",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Fortran"},{default:l(()=>[...n[0]||(n[0]=[s("Fortran",-1)])]),_:1}),n[2]||(n[2]=s("。",-1))]),n[35]||(n[35]=o(`<p>Fortran 曾經在科學計算中很常見。曾幾何時，所有計算機系統都有一個 Fortran 編譯器。Fortran 曾經像今天的 Python 一樣無處不在。因此，如果你是像我這樣的物理學專業學生，在 1990 年代工作，那你肯定學習了 Fortran。</p><p>我一直認為 Fortran 與 BASIC 有點相似，所以每當我需要編寫一個簡短程序，來分析實驗室數據或執行其他一些數值分析時，我都會很快想到 Fortran。我在空閒時用 Fortran 編寫了一個“猜數字”遊戲，其中計算機會在 1 到 100 之間選擇一個數字，並讓我猜這個數字。程序會一直循環，直到我猜對了為止。</p><p>“猜數字”程序練習了編程語言中的幾個概念：如何為變量賦值、如何編寫語句以及如何執行條件判斷和循環。這是學習新編程語言時一個很好的的實踐案例。</p><h3 id="fortran-編程基礎" tabindex="-1">Fortran 編程基礎 <a class="header-anchor" href="#fortran-編程基礎" aria-label="Permalink to “Fortran 編程基礎”">​</a></h3><p>雖然 Fortran 這些年來一直在更新，但我最熟悉的還是 Fortran 77，這是我多年前學習的實現版本。Fortran 是程序員還在打孔卡上編程的年代創建的，因此“經典” Fortran 僅限於處理可以放在打孔卡上的數據。這意味着你只能編寫符合以下限制條件的經典 Fortran 程序（LCTT 譯註：後來的 Fortran 95 等版本已經對這些限制做了很大的改進，如有興趣<strong>建議直接學習新版</strong>）：</p><ul><li>每張卡只允許一行源代碼。</li><li>僅識別第 1-72 列（最後八列，73-80，保留給卡片分類器）。</li><li>行號（“標籤”）位於第 1-5 列。</li><li>程序語句在第 7-72 列。</li><li>要表示跨行，請在第 6 列中輸入一個連續字符（通常是 <code>+</code>）。</li><li>要創建註釋行，請在第 1 列中輸入 <code>C</code> 或 <code>*</code>。</li><li>只有字符 <code>A</code> 到<code>Z</code>（大寫字母）、<code>0</code> 到<code>9</code>（數字）和特殊字符 <code>= + - * / ( ) , . $ &#39; :</code> 和空格能夠使用。</li></ul><p>雖然有這些限制，你仍然可以編寫非常有用和有趣的程序。</p><h3 id="在-fortran-中猜數字" tabindex="-1">在 Fortran 中猜數字 <a class="header-anchor" href="#在-fortran-中猜數字" aria-label="Permalink to “在 Fortran 中猜數字”">​</a></h3><p>通過編寫“猜數字”遊戲來探索 Fortran。這是我的實現代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC</span></span>
<span class="line"><span>C     PROGRAM TO GUESS A NUMBER 1-100</span></span>
<span class="line"><span>CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC</span></span>
<span class="line"><span>      PROGRAM GUESSNUM</span></span>
<span class="line"><span>      INTEGER SEED, NUMBER, GUESS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      PRINT *, &#39;ENTER A RANDOM NUMBER SEED&#39;</span></span>
<span class="line"><span>      READ *, SEED</span></span>
<span class="line"><span>      CALL SRAND(SEED)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      NUMBER = INT( RAND(0) * 100 + 1 )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      PRINT *, &#39;GUESS A NUMBER BETWEEN 1 AND 100&#39;</span></span>
<span class="line"><span> 10   READ *, GUESS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      IF (GUESS.LT.NUMBER) THEN</span></span>
<span class="line"><span>         PRINT *, &#39;TOO LOW&#39;</span></span>
<span class="line"><span>      ELSE IF (GUESS.GT.NUMBER) THEN</span></span>
<span class="line"><span>         PRINT *, &#39;TOO HIGH&#39;</span></span>
<span class="line"><span>      ENDIF</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      IF (GUESS.NE.NUMBER) GOTO 10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      PRINT *, &#39;THATS RIGHT!&#39;</span></span>
<span class="line"><span>      END</span></span></code></pre></div>`,10)),a("p",null,[n[5]||(n[5]=s("如果你熟悉其他編程語言，你大概可以通過閲讀源代碼來弄清楚這個程序在做什麼。前三行是註釋塊，表示程序的功能。第四行 ",-1)),n[6]||(n[6]=a("code",null,"PROGRAM GUESSNUM",-1)),n[7]||(n[7]=s(" 將其標識為一個 ",-1)),a("ruby",null,[p(t,null,{default:l(()=>[...n[3]||(n[3]=[s("程序",-1)])]),_:1}),n[4]||(n[4]=a("rt",null,"program",-1))]),n[8]||(n[8]=s("，並由最後一行的 ",-1)),n[9]||(n[9]=a("code",null,"END",-1)),n[10]||(n[10]=s(" 語句關閉。",-1))]),a("p",null,[n[13]||(n[13]=s("定義變量後，程序會提示用户輸入隨機數種子。Fortran 程序無法從操作系統初始化隨機數生成器，因此你必須始終使用“種子”值和 ",-1)),n[14]||(n[14]=a("code",null,"SRAND",-1)),n[15]||(n[15]=s()),a("ruby",null,[p(t,null,{default:l(()=>[...n[11]||(n[11]=[s("子程序",-1)])]),_:1}),n[12]||(n[12]=a("rt",null,"subroutine",-1))]),n[16]||(n[16]=s(" 啓動隨機數生成器。",-1))]),n[36]||(n[36]=o(`<p>Fortran 使用 <code>RAND(0)</code> 函數生成 0 到 0.999…… 之間的隨機數。參數 <code>0</code> 告訴 <code>RAND</code> 函數生成一個隨機數。將此隨機數乘以 100 以生成 0 到 99.999…… 之間的數字，然後加 1 得到 1 到 100.999…… 之間的值。<code>INT</code> 函數將結果截斷為整數；因此，變量 <code>NUMBER</code> 就是一個介於 1 到 100 之間的隨機數。</p><p>程序會給出提示，然後進入一個循環。Fortran 不支持更現代的編程語言中可用的 <code>while</code> 或 <code>do-while</code> 循環（LCTT 譯註：Fortran 95 等新版支持，也因此在一定程度上減少了 <code>GOTO</code> 的使用）。相反，你必須使用標籤（行號）和 <code>GOTO</code> 語句來構建自己的循環。這就是 <code>READ</code> 語句有一個行號的原因：你可以在循環末尾使用 <code>GOTO</code> 跳轉到此標籤。</p><p>穿孔卡片沒有 <code>&lt;</code>（小於）和 <code>&gt;</code>（大於）符號，因此 Fortran 採用了另一種語法來進行值比較。要測試一個值是否小於另一個值，請使用 <code>.LT.</code>（小於）。要測試一個值是否大於另一個值，請使用 <code>.GT.</code>（大於）。等於和不等於分別是 <code>.EQ.</code> 和 <code>.NE.</code>。</p><p>在每次循環中，程序都會驗證用户的猜測值。如果用户的猜測值小於隨機數，程序打印 <code>TOO LOW</code>，如果猜測大於隨機數，程序打印 <code>TOO HIGH</code>。循環會一直持續，直到用户的猜測值等於目標隨機數為止。</p><p>當循環退出時，程序打印 <code>THATS RIGHT!</code> 並立即結束運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gfortran -Wall -o guess guess.f</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ./guess</span></span>
<span class="line"><span> ENTER A RANDOM NUMBER SEED</span></span>
<span class="line"><span>93759</span></span>
<span class="line"><span> GUESS A NUMBER BETWEEN 1 AND 100</span></span>
<span class="line"><span>50</span></span>
<span class="line"><span> TOO LOW</span></span>
<span class="line"><span>80</span></span>
<span class="line"><span> TOO HIGH</span></span>
<span class="line"><span>60</span></span>
<span class="line"><span> TOO LOW</span></span>
<span class="line"><span>70</span></span>
<span class="line"><span> TOO LOW</span></span>
<span class="line"><span>75</span></span>
<span class="line"><span> TOO HIGH</span></span>
<span class="line"><span>73</span></span>
<span class="line"><span> TOO LOW</span></span>
<span class="line"><span>74</span></span>
<span class="line"><span> THATS RIGHT!</span></span></code></pre></div><p>每次運行程序時，用户都需要輸入不同的隨機數種子。如果你總是輸入相同的種子，程序給出的隨機數也會一直不變。</p><h3 id="在其他語言中嘗試" tabindex="-1">在其他語言中嘗試 <a class="header-anchor" href="#在其他語言中嘗試" aria-label="Permalink to “在其他語言中嘗試”">​</a></h3><p>在學習一門新的編程語言時，這個“猜數字”遊戲是一個很好的入門程序，因為它以非常簡單的方式練習了幾個常見的編程概念。通過用不同的編程語言實現這個簡單的遊戲，你可以弄清一些核心概念以及比較每種語言的細節。</p><p>你有最喜歡的編程語言嗎？如何用你最喜歡的語言來編寫“猜數字”遊戲？跟隨本系列文章來查看你可能感興趣的其他編程語言示例吧。</p><hr>`,11)),a("p",null,[n[18]||(n[18]=s("via: ",-1)),p(e,{href:"https://opensource.com/article/21/1/fortran"},{default:l(()=>[...n[17]||(n[17]=[s("https://opensource.com/article/21/1/fortran",-1)])]),_:1})]),a("p",null,[n[23]||(n[23]=s("作者：",-1)),p(e,{href:"https://opensource.com/users/jim-hall"},{default:l(()=>[...n[19]||(n[19]=[s("Jim Hall",-1)])]),_:1}),n[24]||(n[24]=s(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...n[20]||(n[20]=[s("lujun9972",-1)])]),_:1}),n[25]||(n[25]=s(" 譯者：",-1)),p(e,{href:"https://github.com/unigeorge"},{default:l(()=>[...n[21]||(n[21]=[s("unigeorge",-1)])]),_:1}),n[26]||(n[26]=s(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:l(()=>[...n[22]||(n[22]=[s("wxy",-1)])]),_:1})]),a("p",null,[n[29]||(n[29]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[27]||(n[27]=[s("LCTT",-1)])]),_:1}),n[30]||(n[30]=s(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:l(()=>[...n[28]||(n[28]=[s("Linux中國",-1)])]),_:1}),n[31]||(n[31]=s(" 榮譽推出",-1))])])}const S=i(u,[["render",T]]);export{O as __pageData,S as default};
